use super::*;
use crate::position::AccountPosition;
use crate::payoff::Strategy;

/// The order to attack in.
///
/// EXPIRING promotions first, biggest balance first among them: the whole balance is about to start
/// accruing at once, so the EXPOSURE is what matters, not the rate it currently is not charging.
/// Then the ordinary debts by strategy. Then LIVE promotions last, because a dollar paid there buys
/// nothing while the rate is zero.
pub fn priority_order(debts: &[AccountPosition], strategy: Strategy, as_of: &str, promo_ends: &[(String, String)], urgency_days: i64) -> Vec<AccountPosition> {
    let owed_of = |a: &AccountPosition| a.owed.map(|o| o.minor).unwrap_or(0);
    let mut out = debts.to_vec();
    out.sort_by(|a, b| {
        let sa = promo_state_of(&a.account, as_of, promo_ends, urgency_days);
        let sb = promo_state_of(&b.account, as_of, promo_ends, urgency_days);
        let by_promo = promo_rank(sa).cmp(&promo_rank(sb));
        if by_promo != std::cmp::Ordering::Equal {
            return by_promo;
        }
        let by_rate = b.apr.unwrap_or(0.0).partial_cmp(&a.apr.unwrap_or(0.0)).unwrap_or(std::cmp::Ordering::Equal);
        let by_size = owed_of(a).cmp(&owed_of(b));
        let inner = if sa == PromoState::Expiring {
            // Biggest exposure first, because that is what starts accruing.
            owed_of(b).cmp(&owed_of(a))
        } else if strategy == Strategy::Avalanche {
            by_rate.then(by_size)
        } else {
            by_size.then(by_rate)
        };
        inner.then_with(|| a.account.cmp(&b.account))
    });
    out
}
